def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

n = int(input())
a = list(map(int, input().split()))

# Count the number of 1s and 2s
count_1 = a.count(1)
count_2 = a.count(2)

# Strategy: Start with 2 if possible to get a prime immediately
# Then alternate between 1 and 2 to keep the sum odd
result = []

# If we start with 2, we get 1 prime immediately
if count_2 > 0:
    result.append(2)
    count_2 -= 1
    # Now alternate: 1, 2, 1, 2, ...
    for i in range(count_1 + count_2):
        if i % 2 == 0:
            # Place 1 if available
            if count_1 > 0:
                result.append(1)
                count_1 -= 1
            else:
                result.append(2)
        else:
            # Place 2 if available
            if count_2 > 0:
                result.append(2)
                count_2 -= 1
            else:
                result.append(1)
else:
    # If we start with 1, we don't get a prime immediately
    # But we still want to alternate
    for i in range(count_1 + count_2):
        if i % 2 == 0:
            # Place 1 if available
            if count_1 > 0:
                result.append(1)
                count_1 -= 1
            else:
                result.append(2)
        else:
            # Place 2 if available
            if count_2 > 0:
                result.append(2)
                count_2 -= 1
            else:
                result.append(1)

print(' '.join(map(str, result)))
"}

