n = int(input())
strengths = list(map(int, input().split()))
t = int(input())
queries = [tuple(map(int, input().split())) for _ in range(t)]

# Precompute next non-divisible position for each index
next_non_divisible = [n + 1] * n  # n+1 means no non-divisible position

for i in range(n - 1, -1, -1):
    for j in range(i + 1, n):
        if strengths[j] % strengths[i] != 0:
            next_non_divisible[i] = j
            break

# Process queries
for l, r in queries:
    count = 0
    for i in range(l - 1, r):
        if next_non_divisible[i] > r:
            count += 1
    print(r - l + 1 - count)
"}

