        graph[a].append(b)
        graph[b].append(a)

    max_length = 0
    visited = {i: False for i in range(1, 101)}

    for start in range(1, 101):
        if len(graph[start]) > 0:
            path = []
            length = longest_path(graph, start, visited, path)
            max_length = max(max_length, length)

    print(max_length)

def longest_path(graph, start, visited, path):
    visited[start] = True
    path.append(start)
    max_len = 1

    for neighbor in graph[start]:
        if not visited[neighbor]:
            result = longest_path(graph, neighbor, visited, path)
            max_len = max(max_len, result)

    path.pop()
    visited[start] = False
    return max_len

