import sys

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n + 1))  # 1-indexed
        self.rank = [0] * (n + 1)

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return False
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        else:
            self.parent[y_root] = x_root
            if self.rank[x_root] == self.rank[y_root]:
                self.rank[x_root] += 1
        return True

    def get_components(self):
        components = set()
        for i in range(1, len(self.parent)):
            components.add(self.find(i))
        return components

n, m1, m2 = map(int, sys.stdin.readline().split())

# Initialize Union-Find for both forests
uf_mocha = UnionFind(n)
uf_diana = UnionFind(n)

# Add Mocha's edges
for _ in range(m1):
    u, v = map(int, sys.stdin.readline().split())
    uf_mocha.union(u, v)

# Add Diana's edges
for _ in range(m2):
    u, v = map(int, sys.stdin.readline().split())
    uf_diana.union(u, v)

# Count components in each forest
c1 = len(uf_mocha.get_components())
c2 = len(uf_diana.get_components())

# Maximum edges we can add
h = min(c1, c2) - 1

# Find h edges to add
edges_added = 0
result = []

# Try all pairs of nodes
for u in range(1, n + 1):
    for v in range(u + 1, n + 1):
        # Check if u and v are in different components in both forests
        if uf_mocha.find(u) != uf_mocha.find(v) and uf_diana.find(u) != uf_diana.find(v):
            # Add this edge
            uf_mocha.union(u, v)
            uf_diana.union(u, v)
            result.append((u, v))
            edges_added += 1
            if edges_added == h:
                break
    if edges_added == h:
        break

# Output the result
print(h)
for u, v in result:
    print(u, v)
