import sys

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    idx = 0
    N, Q = map(int, data[idx].split())
    idx += 1

    words = []
    for _ in range(N):
        words.append(data[idx])
        idx += 1

    results = []
    for _ in range(Q):
        p, s = data[idx].split()
        idx += 1

        count = 0
        for word in words:
            if word.startswith(p) and word.endswith(s):
                count += 1

        results.append(str(count))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

