import sys

def prime_factors(n):
    """Return the prime factorization of n as a dictionary: prime -> exponent"""
    factors = {}
    if n % 2 == 0:
        count = 0
        while n % 2 == 0:
            n //= 2
            count += 1
        factors[2] = count

    i = 3
    while i * i <= n:
        if n % i == 0:
            count = 0
            while n % i == 0:
                n //= i
                count += 1
            factors[i] = count
        i += 2

    if n > 1:
        factors[n] = 1

    return factors

def find_p_max(n):
    """Find p_max for number n"""
    factors = prime_factors(n)

    # Find prime with greatest exponent
    max_exponent = -1
    p_max = None

    for prime, exponent in factors.items():
        if exponent > max_exponent:
            max_exponent = exponent
            p_max = prime
        elif exponent == max_exponent:
            if prime < p_max:
                p_max = prime

    return p_max

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    N = int(data[0])
    L = int(data[1])
    A = list(map(int, data[2:2+N]))

    for i in range(1, L + 1):
        if not A:
            break

        p_max = find_p_max(i)

        # Determine if operation is beneficial
        beneficial = (i == 1) or (p_max % i % 2 == 1)

        if beneficial:
            # Double the largest element
            if A:
                A[A.index(max(A))] *= 2
        else:
            # Divide the smallest element by 2 using integer division
            if A:
                A[A.index(min(A))] //= 2

        # Remove elements that became 0
        A = [x for x in A if x != 0]


    # Output
    print(len(A))
    if A:
        print(' '.join(map(str, sorted(A))))

if __name__ == "__main__":
    solve()
