def max_overlap(a, b):
    """Return the maximum overlap where suffix of a matches prefix of b"""
    max_len = 0
    for i in range(1, min(len(a), len(b)) + 1):
        if a[-i:] == b[:i]:
            max_len = i
    return max_len

def solve():
    while True:
        n = int(input())
        if n == 0:
            break
        names = [input().strip() for _ in range(n)]

        # Precompute overlaps
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    overlap[i][j] = max_overlap(names[i], names[j])

        # DP: dp[mask][i] = minimum length to include all cities in mask, ending with city i
        dp = [[float('inf')] * n for _ in range(1 << n)]

        # Initialize with each city alone
        for i in range(n):
            dp[1 << i][i] = len(names[i])

        # DP transition
        for mask in range(1 << n):
            for i in range(n):
                if not (mask & (1 << i)):
                    continue
                for j in range(n):
                    if mask & (1 << j):
                        continue
                    new_mask = mask | (1 << j)
                    dp[new_mask][j] = min(
                        dp[new_mask][j],
                        dp[mask][i] + len(names[j]) - overlap[i][j]
                    )

        # Find the minimum length
        result = min(dp[(1 << n) - 1][i] for i in range(n))
        print(result)

