def solve():
    MOD = 1000000007
    max_n = 105

    # Precompute factorials and inverse factorials for combinations
    fact = [1] * (max_n + 1)
    inv_fact = [1] * (max_n + 1)

    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD

    inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
    for i in range(max_n-1, -1, -1):
        inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

    def comb(n, k):
        if n < k or k < 0:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

    # Precompute Möbius function
    mu = [1] * (max_n + 1)
    is_prime = [True] * (max_n + 1)

    for i in range(2, max_n + 1):
        if is_prime[i]:
            for j in range(i, max_n + 1, i):
                is_prime[j] = False
                mu[j] *= -1
            for j in range(i*i, max_n + 1, i*i):
                mu[j] = 0

    q = int(input())
    for _ in range(q):
        n, f = map(int, input().split())

        # Calculate answer using inclusion-exclusion
        ans = 0
        for k in range(1, n + 1):
            if n % k == 0:
                # k divides n
                # Number of compositions where all parts are divisible by k
                # This is the number of compositions of n/k into f parts
                # with each part ≥ 1
                c = comb((n//k) - 1, f - 1)
                ans = (ans + mu[k] * c) % MOD

        print(ans)

solve()
